    root = Path(root).resolve()
    findings: list[str] = []
"""Discovery and loading for current paper-scoped task packages."""

from __future__ import annotations

import json
import shutil
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Optional

from .contracts import TASK_TYPES, TaskInfo, read_evaluation, validate_task_package
from .settings import TASK_ROOTS, WORKSPACES_DIR


class TaskRepositoryError(RuntimeError):
    pass


class DuplicateTaskError(TaskRepositoryError):
    pass


class InvalidTaskPackageError(TaskRepositoryError):
    pass


@dataclass(frozen=True)
class TaskPackage:
    paper_id: str
    task_type: str
    directory: Path
    category: str
    difficulty: str
    difficulty_reasons: tuple[str, ...]
    package_content_sha256: str

    @property
    def key(self) -> tuple[str, str]:
        return self.task_type, self.paper_id


def _read_json(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"expected JSON object: {path}")
    return value


class TaskRepository:
    """Validated index keyed by ``(task_type, paper_id)``."""

    def __init__(self, roots: Iterable[str | Path] | None = None):
        self.roots = tuple(
            dict.fromkeys(Path(root).expanduser().resolve() for root in (roots or TASK_ROOTS))
        )
        self._index = self._build_index()

    @classmethod
    def from_final(
        cls, task_root: str | Path, *, approved_tasks: Iterable[tuple[str, str]]
    ) -> "TaskRepository":
        """Opt-in final-only loading; explicit (mode, paper_id) approval is required.

        This does not declare packages scientifically publishable or change default
        canonical discovery. Callers must approve the audited version, not all
        packages merely because they reside in a final directory.
        """
        import re

        root = Path(task_root).expanduser().resolve()
        directories = []
        seen = set()
        for mode, paper_id in approved_tasks:
            if mode not in {"autonomous_research", "paper_reproduction"}:
                raise InvalidTaskPackageError(f"invalid_final_mode:{mode}")
            if not re.fullmatch(r"paper_[A-Za-z0-9]+", paper_id):
                raise InvalidTaskPackageError(f"invalid_final_paper_id:{paper_id}")
            if (mode, paper_id) in seen:
                raise DuplicateTaskError(f"duplicate_final_approval:{mode}:{paper_id}")
            seen.add((mode, paper_id))
            directory = root / f"final_verified_{mode}" / paper_id
            if directory.parent.is_symlink() or directory.is_symlink() or not directory.is_dir():
                raise InvalidTaskPackageError(f"invalid_final_directory:{directory}")
            directories.append(directory)
        repository = cls.__new__(cls)
        repository.roots = (root,)
        repository._approved_final_directories = tuple(directories)
        repository._index = repository._build_index()
        return repository

    def _candidate_directories(self) -> list[Path]:
        if hasattr(self, "_approved_final_directories"):
            return list(self._approved_final_directories)
        candidates: list[Path] = []
        for root in self.roots:
            if not root.exists():
                continue
            if root.is_symlink():
                raise InvalidTaskPackageError(f"task_root_is_symlink:{root}")
            for task_type in TASK_TYPES:
                mode_root = root / task_type
                if not mode_root.is_dir():
                    continue
                candidates.extend(
                    path.resolve()
                    for path in sorted(mode_root.iterdir())
                    if path.is_dir() and not path.is_symlink()
                )
        return candidates

    def _build_index(self) -> dict[tuple[str, str], TaskPackage]:
        index: dict[tuple[str, str], TaskPackage] = {}
        paper_modes: dict[str, set[str]] = {}
        for directory in self._candidate_directories():
            validation = validate_task_package(directory)
            if validation.status != "passed":
                raise InvalidTaskPackageError(
                    f"invalid_task_package:{directory}:{';'.join(validation.findings)}"
                )
            info = TaskInfo.model_validate(_read_json(directory / "task_info.json"))
            manifest = _read_json(directory / "package_manifest.json")
            package = TaskPackage(
                paper_id=info.paper_id,
                task_type=info.task_type,
                directory=directory,
                category=info.category,
                difficulty=info.difficulty,
                difficulty_reasons=tuple(info.difficulty_reasons),
                package_content_sha256=str(manifest["package_content_sha256"]),
            )
            if package.key in index:
                previous = index[package.key]
                raise DuplicateTaskError(
                    f"duplicate_task:{package.task_type}:{package.paper_id}:"
                    f"{previous.directory}:{package.directory}"
                )
            index[package.key] = package
            paper_modes.setdefault(package.paper_id, set()).add(package.task_type)
        for paper_id, modes in paper_modes.items():
            if "experiment_validation" in modes and modes & {
                "autonomous_research", "paper_reproduction"
            }:
                raise InvalidTaskPackageError(f"mixed_paper_mode_set:{paper_id}")
        return index

    def get(self, *, paper_id: str, task_type: str) -> TaskPackage:
        try:
            return self._index[(task_type, paper_id)]
        except KeyError as exc:
            raise FileNotFoundError(f"task not found: {task_type}/{paper_id}") from exc

    def list(self, *, task_type: str | None = None) -> list[TaskPackage]:
        values = list(self._index.values())
        if task_type:
            values = [item for item in values if item.task_type == task_type]
"""Adapt the five authored evaluator files to the benchmark scoring runtime."""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any

from ..repository import load_private_reference, load_submission_schema, load_task_package
from ..schemas.task import GroundTruth
from .dual_axis import DUAL_AXIS_POLICY_ID, RESULTS_POLICY_ID, dual_axis_policy, process_rubric
from .rules import associate_rules
from ..contracts.scientific_rubric import scientific_rubric


class EvaluatorAdapterError(RuntimeError):
    pass


class EvaluatorReferenceInvalid(EvaluatorAdapterError):
    pass


@dataclass(frozen=True)
class RuntimeEvaluation:
    ground_truth: dict[str, Any]
    adapter_id: str
    policy_id: str
    task_type: str
    package_content_sha256: str


def _weights(count: int) -> list[int]:
    if count < 1:
        raise EvaluatorReferenceInvalid("reference conclusions must not be empty")
    quotient, remainder = divmod(100, count)
    return [quotient + (index < remainder) for index in range(count)]


def _text(value: Any) -> str:
    return value.strip() if isinstance(value, str) else json.dumps(value, ensure_ascii=False)


def _runtime_contract(
    *, task_type: str, reference: dict[str, dict[str, Any]], submission: dict[str, Any]
) -> dict[str, Any]:
    conclusions = reference["reference_conclusions.json"]["items"]
    rules = reference["scoring_rules.json"]["rules"]
    authored_policy = reference["scoring_rules.json"].get("scoring_policy")
    if authored_policy not in (None, DUAL_AXIS_POLICY_ID, RESULTS_POLICY_ID):
        raise EvaluatorReferenceInvalid(f"unknown authored scoring_policy:{authored_policy}")
    scientific_results = authored_policy == RESULTS_POLICY_ID
    rule_table = associate_rules(reference)
    conclusion_rubric: list[dict[str, Any]] = []
    for conclusion, maximum in zip(conclusions, _weights(len(conclusions))):
        conclusion_id = str(conclusion["conclusion_id"])
        authored_rules = [entry["rule"] for entry in rule_table if conclusion_id in entry["conclusion_ids"]]
        evidence = list(
            dict.fromkeys(
                path
                for rule in authored_rules
                for path in rule.get("binding", {}).get("artifact_paths", [])
            )
        )
        conclusion_rubric.append(
            {
                "id": conclusion_id,
                "max_score": maximum,
                "statement": _text(conclusion["statement"]),
                "acceptance_rule": json.dumps(authored_rules, ensure_ascii=False),
                "required_evidence": evidence or submission["required_files"],
            }
        )
    failures = [
        _text(item.get("description") or item.get("condition") or item)
        if isinstance(item, dict)
        else _text(item)
        for item in reference["critical_failures.json"]["items"]
    ]
    authored_rubric = scientific_rubric(reference["scoring_rules.json"])
    if authored_rubric is not None:
        conclusion_rubric = [{"id": item["id"], "max_score": item["max_score"], "statement": item["description"],
                             "acceptance_rule": json.dumps({"rule_ids": item["rule_ids"]}), "rule_ids": item["rule_ids"],
                             "required_evidence": submission["required_files"]} for item in authored_rubric]
    runtime = {
        "expected_tool_calls": [],
        "expected_result": {
            "key_points": reference["reference_key_points.json"]["items"],
            "conclusions": conclusions,
            "scoring_rules": rules,
        },
        "expected_structured_output": submission["required_files"],
        "evaluation_mode": "dual_axis_100",
        "evaluation_profile": (
            "paper_reproduction" if task_type == "paper_reproduction" else "autonomous_discovery"
        ),
        "score_max": 100,
        "scoring_rubric": process_rubric(
            reproduction=task_type == "paper_reproduction", scientific_results=scientific_results
        ),
      commands: [cp2k]
    command_variables:
      CHEMGRAPH_CP2K_COMMAND: cp2k
    backends: [cp2k]

  periodic:
    conda_name: researchchem-periodic
    description: DFTB+ and SIESTA backend runtime; ABINIT remains separately isolated.
    environment: .envs/general-modern-openmpi5
    conda_packages: [dftbplus, siesta]
    pip_packages: []
    health_checks:
      commands: [dftb+, siesta]
      external_commands:
        - .envs/general-modern-openmpi5/bin/pw.x
        - .envs/periodic-mpich/bin/cp2k
        - .envs/kinetics-legacy/bin/abinit
    command_variables:
      CHEMGRAPH_QE_COMMAND: .envs/general-modern-openmpi5/bin/pw.x
      CHEMGRAPH_CP2K_COMMAND: .envs/periodic-mpich/bin/cp2k
      CHEMGRAPH_DFTBPLUS_COMMAND: dftb+
      CHEMGRAPH_SIESTA_COMMAND: siesta
      CHEMGRAPH_ABINIT_COMMAND: .envs/kinetics-legacy/bin/abinit
    backends: [dftbplus, siesta]

  phonons:
    conda_name: researchchem-phonons
    description: Isolated Phonopy and Phono3py runtime.
    environment: .envs/general-modern-openmpi5
        output_behavior: Writes output.out and restart/trajectory/property files selected in the input.
        example_arguments: ["-i", "input.inp", "-o", "output.out"]
        notes:
          - RUN_TYPE, FORCE_EVAL method, basis/potential data, charge, spin, cell, k-points, cutoffs, SCF, motion, and print sections are Agent choices.

  siesta:
    purpose: Execute a complete SIESTA input deck.
    commands:
      siesta:
        synopsis: "siesta < input.fdf"
        input_mode: stdin_file
        required_files: [input.fdf, pseudopotentials and structure files referenced by it]
        output_behavior: Writes primary output to stdout and SIESTA result/restart files in the job directory.
        example_arguments: []

