for line in s.splitlines():
 m=re.match(r'=== PDF PAGE (\\d+) ===',line)
 if m:page=int(m[1])
 if line.strip() in ['A-D','A-π-D','A-σ-D','2A-2D','2A-π-2D','2A-σ-2D']:
  current={'label':line.strip(),'pages':[page],'rows':[]};blocks.append(current)
 m=re.match(r'"'^'"\\s*(Au|C|H|N|S)\\s+([-+\\d.eE]+)\\s+([-+\\d.eE]+)\\s+([-+\\d.eE]+)\\s*"'$'"',line)
