for i,b in enumerate(blocks):
 b['kind']='junction' if any(r[0]=='Au' for r in b['rows']) else 'isolated'
 print(b['label'],b['kind'],b['pages'],len(b['rows']),dict(collections.Counter(r[0] for r in b['rows'])))
(p/'transport_source_coordinate_blocks.json').write_text(json.dumps(blocks,indent=2))
