  m=Chem.MolFromXYZBlock(xyz);rdDetermineBonds.DetermineBonds(m,charge=0)
  print(b['label'],Chem.MolToSmiles(Chem.RemoveHs(m)),rdMolDescriptors.CalcMolFormula(m))
except Exception as e:print(type(e).__name__,str(e))
PY"

